export default CaptureControls;

import React, { useRef, useState, useEffect, useCallback, useMemo } from 'react';
import { PhotoSize, AppConfig } from '../types';
import { analyzeIDPhotoFrame } from '../services/geminiService';
import { getConfig } from '../services/configService';

// Sub-components
import CaptureStatus from './CaptureStatus';
import CaptureOverlay from './CaptureOverlay';
import CaptureControls from './CaptureControls';
import MobileCameraLink from './MobileCameraLink';
import { t } from '../services/i18n';

// Polyfill definitions for ImageCapture API
interface PhotoCapabilities { redEyeReduction: string; imageHeight: any; imageWidth: any; fillLightMode: string[]; }
interface PhotoSettings { fillLightMode?: string; imageHeight?: number; imageWidth?: number; redEyeReduction?: boolean; }
declare class ImageCapture {
  constructor(track: MediaStreamTrack);
  takePhoto(photoSettings?: PhotoSettings): Promise<Blob>;
  getPhotoCapabilities(): Promise<PhotoCapabilities>;
  grabFrame(): Promise<ImageBitmap>;
}

interface CameraCaptureProps {
  onCapture: (imageSrc: string) => void;
  selectedSize: PhotoSize;
  onSizeChange: (size: PhotoSize) => void;
}

type ValidationStatus = 'searching' | 'analyzing' | 'adjusting' | 'valid';

const SHUTTER_SOUND = "data:audio/mp3;base64,";

const CameraCapture: React.FC<CameraCaptureProps> = ({ onCapture, selectedSize, onSizeChange }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const analysisCanvasRef = useRef<HTMLCanvasElement>(null);
  const shutterAudioRef = useRef<HTMLAudioElement | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string>('');
  const [countdown, setCountdown] = useState<number | null>(null);
  const [isCapturing, setIsCapturing] = useState(false);
  const [devices, setDevices] = useState<MediaDeviceInfo[]>([]);
  const [selectedDeviceId, setSelectedDeviceId] = useState<string>('');
  const [validationStatus, setValidationStatus] = useState<ValidationStatus>('searching');
  const [feedbackMessage, setFeedbackMessage] = useState<string>('Đang xử lý');
  const [instruction, setInstruction] = useState<string>('');
  const [aiLimitReached, setAiLimitReached] = useState(false);

  // Default to TRUE as requested
  const [isAutoCaptureEnabled, setIsAutoCaptureEnabled] = useState(true);

  const hasAutoCapturedForCurrentValidRef = useRef(false);
  const isAnalyzingRef = useRef(false);
  const analysisIntervalRef = useRef<any>(null);
  const lastSpokenRef = useRef<string>('');

  // Use config for i18n
  const config = getConfig();

  const isMobileLink = selectedDeviceId === 'mobile-link';

  useEffect(() => {
    getDevices();
    if (!isMobileLink) {
        startCamera();
    }
    shutterAudioRef.current = new Audio(SHUTTER_SOUND);
    return () => { stopCamera(); if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current); window.speechSynthesis.cancel(); };
  }, []);

  useEffect(() => { 
      if (selectedDeviceId && !isMobileLink) startCamera(selectedDeviceId); 
      if (isMobileLink) stopCamera();
  }, [selectedDeviceId]);

  useEffect(() => {
    if (stream && !countdown && !isCapturing && !aiLimitReached && !isMobileLink) analysisIntervalRef.current = setInterval(performAIAnalysis, 5000);
    else if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current);
    return () => { if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current); };
  }, [stream, countdown, selectedSize, isCapturing, aiLimitReached, isMobileLink]); 

  useEffect(() => {
    if (validationStatus === 'valid' && isAutoCaptureEnabled && !hasAutoCapturedForCurrentValidRef.current && countdown === null && !isCapturing && !isMobileLink) {
          hasAutoCapturedForCurrentValidRef.current = true;
          setCountdown(3);
    } else if (validationStatus !== 'valid') { hasAutoCapturedForCurrentValidRef.current = false; }
  }, [validationStatus, isAutoCaptureEnabled, countdown, isCapturing, isMobileLink]);

  const speak = (text: string, force: boolean = false) => {
      if (!text || (!force && lastSpokenRef.current === text)) return;
      if (force || window.speechSynthesis.speaking) window.speechSynthesis.cancel();
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.lang = config.language === 'en' ? 'en-US' : 'vi-VN'; 
      const voices = window.speechSynthesis.getVoices();
      const voice = voices.find(v => v.lang.startsWith(utterance.lang));
      if (voice) utterance.voice = voice;
      window.speechSynthesis.speak(utterance);
      lastSpokenRef.current = text;
  };

  useEffect(() => {
     if (countdown !== null) return; 
     if (isMobileLink) return;
     if (aiLimitReached) { if (lastSpokenRef.current !== 'AI_STOP') { speak(t('capture.status.analyzing', config), true); lastSpokenRef.current = 'AI_STOP'; } return; }
     if (instruction) {
         if (validationStatus === 'valid') { if (lastSpokenRef.current !== 'ok') { speak(t('capture.msg.valid', config), true); lastSpokenRef.current = 'ok'; } } 
         else { speak(instruction); }
     }
  }, [instruction, validationStatus, countdown, aiLimitReached, isMobileLink]);

  const getCropDimensions = (sourceW: number, sourceH: number) => {
    let targetRatio = 2/3; 
    if (selectedSize === PhotoSize.SIZE_5X5) targetRatio = 1;
    if (selectedSize === PhotoSize.SIZE_3X4) targetRatio = 3/4;
    const sourceRatio = sourceW / sourceH;
    let cropW, cropH, startX, startY;
    if (sourceRatio > targetRatio) { cropH = sourceH; cropW = cropH * targetRatio; startX = (sourceW - cropW) / 2; startY = 0; }
    else { cropW = sourceW; cropH = cropW / targetRatio; startX = 0; startY = (sourceH - cropH) * 0.65; }
    return { x: Math.floor(startX), y: Math.floor(startY), w: Math.floor(cropW), h: Math.floor(cropH) };
  };

  const performAIAnalysis = async () => {
    if (isAnalyzingRef.current || !videoRef.current || !analysisCanvasRef.current || aiLimitReached) return;
    try {
      isAnalyzingRef.current = true;
      const video = videoRef.current;
      const canvas = analysisCanvasRef.current;
      const ctx = canvas.getContext('2d');
      if (video.readyState === 4 && ctx) {
        const crop = getCropDimensions(video.videoWidth, video.videoHeight);
        const analysisH = 320;
        const analysisW = Math.floor(analysisH * (crop.w / crop.h));
        canvas.width = analysisW; canvas.height = analysisH;
        ctx.save(); ctx.translate(canvas.width, 0); ctx.scale(-1, 1);
        ctx.drawImage(video, crop.x, crop.y, crop.w, crop.h, 0, 0, canvas.width, canvas.height);
        ctx.restore();
        if (validationStatus === 'searching') setValidationStatus('analyzing');
        const result = await analyzeIDPhotoFrame(canvas.toDataURL('image/jpeg', 0.6));
        if (result.feedback === 'AI_LIMIT') { setAiLimitReached(true); setValidationStatus('valid'); setFeedbackMessage('AI TẠM NGƯNG'); return; }
        if (!result.faceDetected) { setValidationStatus('searching'); setFeedbackMessage('Không tìm thấy mặt'); setInstruction('Di chuyển vào khung hình'); }
        else if (result.isCompliant) { setValidationStatus('valid'); setFeedbackMessage('ĐẠT CHUẨN'); setInstruction(result.instruction || 'Giữ nguyên tư thế!'); }
        else { setValidationStatus('adjusting'); setFeedbackMessage(result.feedback || 'Cần điều chỉnh'); setInstruction(result.instruction || 'Chỉnh lại tư thế'); }
      }
    } catch (err) {} finally { isAnalyzingRef.current = false; }
  };

  const getDevices = async () => {
    const all = await navigator.mediaDevices.enumerateDevices();
    const video = all.filter(d => d.kind === 'videoinput');
    setDevices(video);
    const canon = video.find(d => d.label.toLowerCase().includes('canon') || d.label.toLowerCase().includes('eos'));
    if (canon) setSelectedDeviceId(canon.deviceId);
  };

  const startCamera = async (deviceId?: string) => {
    stopCamera();
    try {
      const constraints = { video: { deviceId: deviceId ? { exact: deviceId } : undefined, width: { ideal: 3840 }, height: { ideal: 2160 } } };
      let s; try { s = await navigator.mediaDevices.getUserMedia(constraints); } catch { s = await navigator.mediaDevices.getUserMedia({ video: { deviceId: deviceId ? { exact: deviceId } : undefined, width: { ideal: 1920 }, height: { ideal: 1080 } } }); }
      setStream(s); if (videoRef.current) videoRef.current.srcObject = s;
    } catch { setError('Lỗi camera'); }
  };

  const stopCamera = () => { if (stream) { stream.getTracks().forEach(t => t.stop()); setStream(null); } };

  const captureFrame = useCallback(async () => {
    setIsCapturing(true); if (shutterAudioRef.current) { shutterAudioRef.current.currentTime = 0; shutterAudioRef.current.play().catch(() => {}); }
    if (!videoRef.current || !canvasRef.current) { setIsCapturing(false); return; }
    const video = videoRef.current; const canvas = canvasRef.current; const ctx = canvas.getContext('2d');
    let src: any = video, sw = video.videoWidth, sh = video.videoHeight;
    if (stream) {
        const track = stream.getVideoTracks()[0];
        if (track && 'ImageCapture' in window) {
            try {
                const ic = new (window as any).ImageCapture(track); const blob = await ic.takePhoto();
                const hiImg = new Image(); hiImg.src = URL.createObjectURL(blob);
                await new Promise(r => hiImg.onload = r); src = hiImg; sw = hiImg.width; sh = hiImg.height;
            } catch {}
        }
    }
    if (ctx && sw > 0) {
        const crop = getCropDimensions(sw, sh);
        canvas.width = crop.w; canvas.height = crop.h;
        ctx.translate(canvas.width, 0); ctx.scale(-1, 1); ctx.drawImage(src, crop.x, crop.y, crop.w, crop.h, 0, 0, canvas.width, canvas.height);
        onCapture(canvas.toDataURL('image/jpeg', 1.0));
    }
    setIsCapturing(false);
  }, [onCapture, selectedSize, stream]);

  // Handler for file upload
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        if (event.target?.result) {
          onCapture(event.target.result as string);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  useEffect(() => {
    if (countdown === null) return;
    if (countdown > 0) speak(countdown.toString(), true);
    if (countdown > 0) { const t = setTimeout(() => setCountdown(countdown - 1), 1000); return () => clearTimeout(t); }
    else if (countdown === 0) { captureFrame(); setCountdown(null); }
  }, [countdown, captureFrame]);

  const topMarginPercent = useMemo(() => selectedSize === PhotoSize.SIZE_3X4 ? 7.5 : selectedSize === PhotoSize.SIZE_5X5 ? 6 : 7, [selectedSize]);
  const marginText = useMemo(() => selectedSize === PhotoSize.SIZE_4X6 ? "CÁCH MÉP 4MM" : "CÁCH MÉP 3MM", [selectedSize]);
  const getOverlayColor = () => validationStatus === 'valid' ? '#22c55e' : validationStatus === 'adjusting' ? '#facc15' : validationStatus === 'analyzing' ? '#60a5fa' : '#ef4444';

  return (
    <div className="flex flex-col h-[100dvh] w-full bg-gray-900 relative select-none overflow-hidden touch-none py-safe">

      {/* 1. Header Area: Status */}
      <div className="shrink-0 z-20 w-full relative">
        <CaptureStatus 
          validationStatus={validationStatus}
          feedbackMessage={feedbackMessage}
          instruction={instruction}
          devices={devices}
          selectedDeviceId={selectedDeviceId}
          onDeviceChange={setSelectedDeviceId}
          config={config}
        />
      </div>

      {/* 2. Main Content: Video Feed */}
      <div className="flex-1 flex items-center justify-center w-full relative min-h-0 py-2">
         {isMobileLink && (
             <MobileCameraLink 
                config={config}
                selectedSize={selectedSize}
                onPhotoReceived={onCapture}
                onCancel={() => {
                    const firstWebcam = devices.find(d => d.kind === 'videoinput');
                    setSelectedDeviceId(firstWebcam?.deviceId || '');
                }}
             />
         )}

         <div className={`relative transition-all duration-300 bg-black rounded-lg overflow-hidden flex items-center justify-center border-4 h-full aspect-[2/3] md:aspect-[3/4] lg:aspect-[2/3] max-w-full max-h-full ${validationStatus === 'valid' ? 'border-green-500 shadow-[0_0_30px_rgba(34,197,94,0.6)]' : validationStatus === 'adjusting' ? 'border-yellow-400' : validationStatus === 'analyzing' ? 'border-brand-400' : 'border-red-500'}`}>
            {!isMobileLink && (
                <>
                    <video ref={videoRef} autoPlay playsInline className="absolute inset-0 w-full h-full object-cover transform -scale-x-100" />
                    <CaptureOverlay 
                        selectedSize={selectedSize}
                        validationStatus={validationStatus}
                        aiLimitReached={aiLimitReached}
                        topMarginPercent={topMarginPercent}
                        marginText={marginText}
                        getOverlayColor={getOverlayColor}
                        config={config}
                    />
                    {(countdown !== null || isCapturing) && (
                    <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/60 z-40 backdrop-blur-sm">
                        {isCapturing ? <><div className="w-16 h-16 border-4 border-white border-t-transparent rounded-full animate-spin mb-4" /><span className="text-white font-bold tracking-widest">{t('capture.label.processing', config)}</span></> : <span className="text-[120px] md:text-[180px] font-bold text-white animate-ping">{countdown}</span>}
                    </div>
                    )}
                </>
            )}
         </div>
      </div>

      {/* 3. Footer Area: Controls */}
      {!isMobileLink && (
        <div className="shrink-0 z-20 w-full pb-2 pt-2">
            <input type="file" ref={fileInputRef} onChange={handleFileUpload} accept="image/*" className="hidden" />
            <CaptureControls 
                isAutoCaptureEnabled={isAutoCaptureEnabled}
                validationStatus={validationStatus}
                countdown={countdown}
                isCapturing={isCapturing}
                onAutoCaptureToggle={() => setIsAutoCaptureEnabled(!isAutoCaptureEnabled)}
                onCaptureClick={() => setCountdown(3)}
                onMobileLink={() => setSelectedDeviceId('mobile-link')}
                onUpload={() => fileInputRef.current?.click()}
                config={config}
            />
        </div>
      )}

      <canvas ref={canvasRef} className="hidden" />
      <canvas ref={analysisCanvasRef} className="hidden" />
      <style>{`@keyframes scan { 0% { top: 0%; opacity: 0; } 10% { opacity: 1; } 90% { opacity: 1; } 100% { top: 100%; opacity: 0; } }`}</style>
    </div>
  );
};

export default CameraCapture;

import React, { useRef, useState, useEffect, useCallback, useMemo } from 'react';
import { PhotoSize, AppConfig } from '../types';
import { analyzeIDPhotoFrame } from '../services/geminiService';
import { savePhotoToCloud } from '../services/databaseService';
import { t } from '../services/i18n';

interface MobileCaptureClientProps {
  sessionId: string;
  config: AppConfig;
  initialSize?: PhotoSize;
}

type ValidationStatus = 'searching' | 'analyzing' | 'adjusting' | 'valid';

const SHUTTER_SOUND = "data:audio/mp3;base64,";

const MobileCaptureClient: React.FC<MobileCaptureClientProps> = ({ sessionId, config, initialSize = PhotoSize.SIZE_4X6 }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const analysisCanvasRef = useRef<HTMLCanvasElement>(null);
  const shutterAudioRef = useRef<HTMLAudioElement | null>(null);
  const analysisIntervalRef = useRef<any>(null);
  const isAnalyzingRef = useRef(false);
  const hasAutoCapturedRef = useRef(false);
  const lastSpokenRef = useRef<string>('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [stream, setStream] = useState<MediaStream | null>(null);
  const [capturedImage, setCapturedImage] = useState<string | null>(null);
  const [isUploading, setIsUploading] = useState(false);
  const [isCompleted, setIsCompleted] = useState(false);
  const [countdown, setCountdown] = useState<number | null>(null);
  const [validationStatus, setValidationStatus] = useState<ValidationStatus>('searching');
  const [feedbackMessage, setFeedbackMessage] = useState<string>(t('capture.label.processing', config));
  const [instruction, setInstruction] = useState<string>('');
  const [cameraError, setCameraError] = useState('');
  const [facingMode, setFacingMode] = useState<'user' | 'environment'>('user');

  // Default to TRUE for Auto Capture
  const [isAutoCaptureEnabled, setIsAutoCaptureEnabled] = useState(true);

  // --- Voice Synthesis Logic ---
  const speak = (text: string, force: boolean = false) => {
    if (!text || (!force && lastSpokenRef.current === text)) return;

    // Mobile often requires user interaction first, but we attempt anyway
    if (force || window.speechSynthesis.speaking) window.speechSynthesis.cancel();

    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = config.language === 'en' ? 'en-US' : 'vi-VN'; 

    const voices = window.speechSynthesis.getVoices();
    const voice = voices.find(v => v.lang.startsWith(utterance.lang));
    if (voice) utterance.voice = voice;

    // Mobile quirk: high rate helps responsiveness
    utterance.rate = 1.0; 

    window.speechSynthesis.speak(utterance);
    lastSpokenRef.current = text;
  };

  // Speak instructions on change
  useEffect(() => {
     if (countdown !== null) return; 
     if (instruction) {
         if (validationStatus === 'valid') { 
            if (lastSpokenRef.current !== 'ok') { 
                speak(t('capture.msg.valid', config), true); 
                lastSpokenRef.current = 'ok'; 
            } 
         } else { 
            speak(instruction); 
         }
     }
  }, [instruction, validationStatus, countdown]);

  const startCamera = async (mode: 'user' | 'environment') => {
    if (stream) stream.getTracks().forEach(track => track.stop());
    const constraints: MediaStreamConstraints = { video: { facingMode: mode, width: { ideal: 1920 }, height: { ideal: 1080 } } };
    try {
      const s = await navigator.mediaDevices.getUserMedia(constraints);
      setStream(s);
      if (videoRef.current) videoRef.current.srcObject = s;
    } catch (e) {
      setCameraError('Máy ảnh chưa được cấp quyền.');
    }
  };

  useEffect(() => {
    startCamera(facingMode);
    shutterAudioRef.current = new Audio(SHUTTER_SOUND);
    return () => {
      if (stream) stream.getTracks().forEach(t => t.stop());
      if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current);
      window.speechSynthesis.cancel();
    };
  }, [facingMode]);

  useEffect(() => {
    if (stream && !countdown && !capturedImage) {
      analysisIntervalRef.current = setInterval(performAIAnalysis, 3000);
    } else {
      if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current);
    }
    return () => { if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current); };
  }, [stream, countdown, capturedImage]);

  useEffect(() => {
    if (isAutoCaptureEnabled && validationStatus === 'valid' && !hasAutoCapturedRef.current && countdown === null && !capturedImage) {
      hasAutoCapturedRef.current = true;
      setCountdown(3);
    } else if (validationStatus !== 'valid') {
      hasAutoCapturedRef.current = false;
    }
  }, [validationStatus, isAutoCaptureEnabled, countdown, capturedImage]);

  const performAIAnalysis = async () => {
    if (isAnalyzingRef.current || !videoRef.current || !analysisCanvasRef.current) return;
    try {
      isAnalyzingRef.current = true;
      const video = videoRef.current;
      const canvas = analysisCanvasRef.current;
      const ctx = canvas.getContext('2d');
      if (video.readyState === 4 && ctx) {
        const crop = getCropDimensions(video.videoWidth, video.videoHeight);
        canvas.width = 240; canvas.height = 360;
        if (facingMode === 'user') { ctx.translate(canvas.width, 0); ctx.scale(-1, 1); }
        ctx.drawImage(video, crop.x, crop.y, crop.w, crop.h, 0, 0, canvas.width, canvas.height);
        const result = await analyzeIDPhotoFrame(canvas.toDataURL('image/jpeg', 0.5));
        if (!result.faceDetected) {
            setValidationStatus('searching'); setFeedbackMessage(t('capture.msg.no_face', config)); setInstruction(t('capture.msg.move_in', config));
        } else if (result.isCompliant) {
            setValidationStatus('valid'); setFeedbackMessage(t('capture.status.valid', config)); setInstruction(t('capture.msg.valid', config));
        } else {
            setValidationStatus('adjusting'); setFeedbackMessage(result.feedback || t('capture.status.adjusting', config)); setInstruction(result.instruction || '');
        }
      }
    } catch (err) {} finally { isAnalyzingRef.current = false; }
  };

  const getCropDimensions = (sourceW: number, sourceH: number) => {
    let targetRatio = initialSize === PhotoSize.SIZE_5X5 ? 1 : (initialSize === PhotoSize.SIZE_3X4 ? 3/4 : 2/3);
    const sourceRatio = sourceW / sourceH;
    let cropW, cropH, startX, startY;
    if (sourceRatio > targetRatio) { cropH = sourceH; cropW = cropH * targetRatio; startX = (sourceW - cropW) / 2; startY = 0; }
    else { cropW = sourceW; cropH = cropW / targetRatio; startX = 0; startY = (sourceH - cropH) * 0.5; }
    return { x: Math.floor(startX), y: Math.floor(startY), w: Math.floor(cropW), h: Math.floor(cropH) };
  };

  const captureFrame = useCallback(() => {
    if (shutterAudioRef.current) shutterAudioRef.current.play().catch(() => {});
    if (!videoRef.current || !canvasRef.current) return;
    const video = videoRef.current;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    const crop = getCropDimensions(video.videoWidth, video.videoHeight);

    canvas.height = 1000;
    canvas.width = Math.floor(1000 * (crop.w/crop.h));

    if (facingMode === 'user') { ctx?.translate(canvas.width, 0); ctx?.scale(-1, 1); }
    ctx?.drawImage(video, crop.x, crop.y, crop.w, crop.h, 0, 0, canvas.width, canvas.height);

    setCapturedImage(canvas.toDataURL('image/jpeg', 0.8));
  }, [facingMode, initialSize]);

  // Handler for file upload
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        if (event.target?.result) {
          setCapturedImage(event.target.result as string);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  useEffect(() => {
    if (countdown === null) return;
    if (countdown > 0) {
        speak(countdown.toString(), true); // Speak count
        const timer = setTimeout(() => setCountdown(countdown - 1), 1000);
        return () => clearTimeout(timer);
    } else {
        captureFrame();
        setCountdown(null);
    }
  }, [countdown, captureFrame]);

  const handleUpload = async () => {
    if (!capturedImage || !sessionId) return;
    setIsUploading(true);
    try {
        const resultId = await savePhotoToCloud({
            id: sessionId,
            dataUrl: capturedImage,
            timestamp: Date.now(),
            settings: { size: initialSize, background: 'original' as any, beauty: {} as any, printQuantity: 1 }
        }, config.googleScriptUrl);

        if (resultId) setIsCompleted(true);
        else alert('Đồng bộ thất bại. Vui lòng thử lại.');
    } catch (e) { 
        alert('Lỗi kết nối Cloud.'); 
    } finally { 
        setIsUploading(false); 
    }
  };

  const topMarginPercent = useMemo(() => initialSize === PhotoSize.SIZE_3X4 ? 7.5 : initialSize === PhotoSize.SIZE_5X5 ? 6 : 7, [initialSize]);
  const overlayColor = validationStatus === 'valid' ? '#22c55e' : validationStatus === 'adjusting' ? '#facc15' : '#ef4444';

  if (isCompleted) {
    return (
        <div className="h-[100dvh] bg-brand-600 flex flex-col items-center justify-center text-white p-8 text-center animate-fadeIn">
            <div className="w-20 h-20 bg-white rounded-full flex items-center justify-center mb-8 shadow-2xl">
                <svg className="w-10 h-10 text-brand-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"></path></svg>
            </div>
            <h2 className="text-2xl font-black mb-4 uppercase">Gửi thành công!</h2>
            <p className="opacity-90">ID phiên: <span className="font-mono bg-black/20 px-2 rounded">{sessionId}</span></p>
            <p className="mt-4 opacity-80 text-sm">Hãy quay lại màn hình máy tính.</p>
        </div>
    );
  }

  return (
    <div className="h-[100dvh] bg-black flex flex-col relative overflow-hidden touch-none py-safe">
        <div className="absolute top-0 left-0 right-0 p-4 z-50 flex flex-col items-center pointer-events-none">
            {!capturedImage && (
                <div className={`px-6 py-4 rounded-3xl backdrop-blur-md border-2 transition-all duration-300 text-center shadow-lg flex flex-col ${validationStatus === 'valid' ? 'bg-green-600/90 border-green-400' : 'bg-black/60 border-white/20'}`}>
                    <span className="text-white font-black text-xs uppercase tracking-widest mb-1 block">{feedbackMessage}</span>
                    <span className="text-white text-lg font-bold leading-tight px-2">{instruction}</span>
                </div>
            )}
            <div className="mt-2 text-[8px] text-white/40 font-mono">Phiên: {sessionId}</div>
        </div>

        <div className="flex-1 relative flex items-center justify-center bg-gray-900 overflow-hidden">
            {cameraError ? (
                <div className="text-white text-center p-6 bg-black/80 rounded-2xl border border-red-500 m-4">
                    <p className="font-bold">{cameraError}</p>
                    <button onClick={() => window.location.reload()} className="mt-4 px-6 py-2 bg-white text-black rounded-full font-bold">Thử lại</button>
                </div>
            ) : capturedImage ? (
                <div className="relative h-full w-full flex items-center justify-center p-4">
                    <img src={capturedImage} className="max-h-full max-w-full rounded shadow-2xl" alt="Preview" />
                </div>
            ) : (
                <>
                    <video ref={videoRef} autoPlay playsInline className={`absolute inset-0 w-full h-full object-cover ${facingMode === 'user' ? 'transform -scale-x-100' : ''}`} />
                    <svg viewBox="0 0 100 100" className="absolute inset-0 w-full h-full opacity-90 pointer-events-none z-20">
                        <defs><mask id="m"><rect x="0" y="0" width="100" height="100" fill="white" /><ellipse cx="50" cy={topMarginPercent + 35} rx={32} ry={38} fill="black" /></mask></defs>
                        <rect x="0" y="0" width="100" height="100" fill="rgba(0,0,0,0.6)" mask="url(#m)" />
                        <ellipse cx="50" cy={topMarginPercent + 35} rx={32} ry={38} fill="none" stroke={overlayColor} strokeWidth="0.5" strokeDasharray="2,2" />
                    </svg>
                </>
            )}

            {countdown !== null && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/40 z-[100] backdrop-blur-sm">
                    <span className="text-9xl font-black text-white animate-ping">{countdown}</span>
                </div>
            )}
        </div>

        <div className="bg-black/95 p-6 pb-12 z-50 flex flex-col items-center gap-4">
            <input type="file" ref={fileInputRef} onChange={handleFileUpload} accept="image/*" className="hidden" />

            {capturedImage ? (
                <div className="flex w-full gap-4 max-w-sm">
                    <button onClick={() => setCapturedImage(null)} disabled={isUploading} className="flex-1 py-4 bg-gray-800 text-white rounded-2xl font-bold uppercase text-xs">Chụp lại</button>
                    <button onClick={handleUpload} disabled={isUploading} className="flex-[2] py-4 bg-brand-600 text-white rounded-2xl font-bold shadow-xl flex items-center justify-center gap-2 uppercase text-xs">
                        {isUploading ? "Đang gửi..." : "Sử dụng ảnh này"}
                    </button>
                </div>
            ) : (
                <div className="flex items-center justify-between w-full max-w-sm px-4 gap-4">
                    {/* Upload Button */}
                    <button onClick={() => fileInputRef.current?.click()} className="w-14 h-14 rounded-full bg-gray-800 flex items-center justify-center text-gray-400 border border-gray-600 active:bg-gray-700 transition-all" title="Upload">
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12"></path></svg>
                    </button>

                    <button onClick={() => setFacingMode(f => f === 'user' ? 'environment' : 'user')} className="w-14 h-14 rounded-full bg-white/20 flex items-center justify-center text-white backdrop-blur border border-white/10 active:bg-white/30 transition-all">
                        <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path></svg>
                    </button>

                    <button onClick={() => setCountdown(3)} disabled={countdown !== null} className={`w-24 h-24 rounded-full border-4 flex items-center justify-center transition-all ${validationStatus === 'valid' ? 'border-green-500 bg-white shadow-[0_0_30px_rgba(34,197,94,0.5)]' : 'border-gray-500 bg-gray-700'}`}>
                        <div className={`w-20 h-20 rounded-full transition-colors ${validationStatus === 'valid' ? 'bg-green-600' : 'bg-gray-500'}`}></div>
                    </button>

                    <button onClick={() => setIsAutoCaptureEnabled(!isAutoCaptureEnabled)} className={`w-14 h-14 rounded-xl flex flex-col items-center justify-center border-2 transition-all active:scale-95 ${isAutoCaptureEnabled ? 'bg-brand-600 border-brand-400 text-white shadow-lg shadow-brand-500/50' : 'bg-gray-800 border-gray-600 text-gray-500'}`}>
                        <svg className={`w-6 h-6 mb-0.5 ${isAutoCaptureEnabled ? 'animate-pulse' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z"></path></svg>
                        <span className="text-[9px] font-black uppercase">Auto</span>
                    </button>
                </div>
            )}
        </div>
        <canvas ref={canvasRef} className="hidden" />
        <canvas ref={analysisCanvasRef} className="hidden" />
    </div>
  );
};

