  const analysisIntervalRef = useRef<any>(null);
  const isAnalyzingRef = useRef(false);
  const hasAutoCapturedRef = useRef(false);
  const lastSpokenRef = useRef<string>('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [stream, setStream] = useState<MediaStream | null>(null);
  const [capturedImage, setCapturedImage] = useState<string | null>(null);
  const [isUploading, setIsUploading] = useState(false);
  const [isCompleted, setIsCompleted] = useState(false);
  const [countdown, setCountdown] = useState<number | null>(null);
  const [validationStatus, setValidationStatus] = useState<ValidationStatus>('searching');
  const [feedbackMessage, setFeedbackMessage] = useState<string>(t('capture.label.processing', config));
  const [instruction, setInstruction] = useState<string>('');
  const [cameraError, setCameraError] = useState('');
  const [facingMode, setFacingMode] = useState<'user' | 'environment'>('user');

  // Default to TRUE for Auto Capture
  const [isAutoCaptureEnabled, setIsAutoCaptureEnabled] = useState(true);

  // --- Voice Synthesis Logic ---
  const speak = (text: string, force: boolean = false) => {
    if (!text || (!force && lastSpokenRef.current === text)) return;

    // Mobile often requires user interaction first, but we attempt anyway
    if (force || window.speechSynthesis.speaking) window.speechSynthesis.cancel();

    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = config.language === 'en' ? 'en-US' : 'vi-VN'; 

    const voices = window.speechSynthesis.getVoices();
    const voice = voices.find(v => v.lang.startsWith(utterance.lang));
    if (voice) utterance.voice = voice;

    // Mobile quirk: high rate helps responsiveness
    utterance.rate = 1.0; 

    window.speechSynthesis.speak(utterance);
    lastSpokenRef.current = text;
  };

  // Speak instructions on change
  useEffect(() => {
     if (countdown !== null) return; 
     if (instruction) {
         if (validationStatus === 'valid') { 
            if (lastSpokenRef.current !== 'ok') { 
                speak(t('capture.msg.valid', config), true); 
                lastSpokenRef.current = 'ok'; 
            } 
         } else { 
            speak(instruction); 
         }
     }
  }, [instruction, validationStatus, countdown]);

  const startCamera = async (mode: 'user' | 'environment') => {
    if (stream) stream.getTracks().forEach(track => track.stop());
    const constraints: MediaStreamConstraints = { video: { facingMode: mode, width: { ideal: 1920 }, height: { ideal: 1080 } } };
    try {
      const s = await navigator.mediaDevices.getUserMedia(constraints);
      setStream(s);
      if (videoRef.current) videoRef.current.srcObject = s;
    } catch (e) {
      setCameraError('Máy ảnh chưa được cấp quyền.');
    }
  };

  useEffect(() => {
    startCamera(facingMode);
    shutterAudioRef.current = new Audio(SHUTTER_SOUND);
    return () => {
      if (stream) stream.getTracks().forEach(t => t.stop());
      if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current);
      window.speechSynthesis.cancel();
    };
  }, [facingMode]);

  useEffect(() => {
    if (stream && !countdown && !capturedImage) {
      analysisIntervalRef.current = setInterval(performAIAnalysis, 3000);
    } else {
      if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current);
    }
    return () => { if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current); };
  }, [stream, countdown, capturedImage]);

  useEffect(() => {
    if (isAutoCaptureEnabled && validationStatus === 'valid' && !hasAutoCapturedRef.current && countdown === null && !capturedImage) {
      hasAutoCapturedRef.current = true;
      setCountdown(3);
    } else if (validationStatus !== 'valid') {
      hasAutoCapturedRef.current = false;
    }
  }, [validationStatus, isAutoCaptureEnabled, countdown, capturedImage]);

  const performAIAnalysis = async () => {
    if (isAnalyzingRef.current || !videoRef.current || !analysisCanvasRef.current) return;
    try {
      isAnalyzingRef.current = true;
      const video = videoRef.current;
      const canvas = analysisCanvasRef.current;
      const ctx = canvas.getContext('2d');
      if (video.readyState === 4 && ctx) {
        const crop = getCropDimensions(video.videoWidth, video.videoHeight);
        canvas.width = 240; canvas.height = 360;
        if (facingMode === 'user') { ctx.translate(canvas.width, 0); ctx.scale(-1, 1); }
        ctx.drawImage(video, crop.x, crop.y, crop.w, crop.h, 0, 0, canvas.width, canvas.height);
        const result = await analyzeIDPhotoFrame(canvas.toDataURL('image/jpeg', 0.5));
        if (!result.faceDetected) {
            setValidationStatus('searching'); setFeedbackMessage(t('capture.msg.no_face', config)); setInstruction(t('capture.msg.move_in', config));
        } else if (result.isCompliant) {
            setValidationStatus('valid'); setFeedbackMessage(t('capture.status.valid', config)); setInstruction(t('capture.msg.valid', config));
        } else {
            setValidationStatus('adjusting'); setFeedbackMessage(result.feedback || t('capture.status.adjusting', config)); setInstruction(result.instruction || '');
        }
      }
    } catch (err) {} finally { isAnalyzingRef.current = false; }
  };

  const getCropDimensions = (sourceW: number, sourceH: number) => {
    let targetRatio = initialSize === PhotoSize.SIZE_5X5 ? 1 : (initialSize === PhotoSize.SIZE_3X4 ? 3/4 : 2/3);
    const sourceRatio = sourceW / sourceH;
    let cropW, cropH, startX, startY;
    if (sourceRatio > targetRatio) { cropH = sourceH; cropW = cropH * targetRatio; startX = (sourceW - cropW) / 2; startY = 0; }
    else { cropW = sourceW; cropH = cropW / targetRatio; startX = 0; startY = (sourceH - cropH) * 0.5; }
    return { x: Math.floor(startX), y: Math.floor(startY), w: Math.floor(cropW), h: Math.floor(cropH) };
  };

  const captureFrame = useCallback(() => {
    if (shutterAudioRef.current) shutterAudioRef.current.play().catch(() => {});
    if (!videoRef.current || !canvasRef.current) return;
    const video = videoRef.current;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    const crop = getCropDimensions(video.videoWidth, video.videoHeight);

    // Resize lại để tối ưu tốc độ upload, tránh lỗi Google Apps Script payload quá lớn
    canvas.height = 1200; // Đủ nét cho in 4x6
    canvas.width = Math.floor(1200 * (crop.w/crop.h));

    if (facingMode === 'user') { ctx?.translate(canvas.width, 0); ctx?.scale(-1, 1); }
    ctx?.drawImage(video, crop.x, crop.y, crop.w, crop.h, 0, 0, canvas.width, canvas.height);

    // Sử dụng chất lượng 0.7 để giảm dung lượng file base64
    setCapturedImage(canvas.toDataURL('image/jpeg', 0.7));
  }, [facingMode, initialSize]);

  // Handler for file upload
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        if (event.target?.result) {
          // Resize ảnh upload nếu quá lớn
          const img = new Image();
          img.onload = () => {
             const canvas = document.createElement('canvas');
             const ctx = canvas.getContext('2d');
             // Limit height to 1200px
             const scale = Math.min(1, 1200 / img.height);
             canvas.width = img.width * scale;
             canvas.height = img.height * scale;
             ctx?.drawImage(img, 0, 0, canvas.width, canvas.height);
             setCapturedImage(canvas.toDataURL('image/jpeg', 0.7));
          }
          img.src = event.target.result as string;
        }
      };
      reader.readAsDataURL(file);
    }
    // Reset giá trị input để có thể chọn lại cùng một file nếu muốn
    e.target.value = '';
  };

  useEffect(() => {
    if (countdown === null) return;
    if (countdown > 0) {
        speak(countdown.toString(), true); // Speak count
        const timer = setTimeout(() => setCountdown(countdown - 1), 1000);
        return () => clearTimeout(timer);
    } else {
        captureFrame();
        setCountdown(null);
    }
  }, [countdown, captureFrame]);

  const handleUpload = async () => {
    if (!capturedImage || !sessionId) return;
    setIsUploading(true);
    try {
        const resultId = await savePhotoToCloud({
            id: sessionId,
            dataUrl: capturedImage,
            timestamp: Date.now(),
            settings: { size: initialSize, background: 'original' as any, beauty: {} as any, printQuantity: 1 }
        }, config.googleScriptUrl);

        if (resultId) setIsCompleted(true);
        else alert('Đồng bộ thất bại. Vui lòng thử lại.');
    } catch (e) { 
        alert('Lỗi kết nối Cloud.'); 
    } finally { 
        setIsUploading(false); 
    }
  };

  const topMarginPercent = useMemo(() => initialSize === PhotoSize.SIZE_3X4 ? 7.5 : initialSize === PhotoSize.SIZE_5X5 ? 6 : 7, [initialSize]);
  const overlayColor = validationStatus === 'valid' ? '#22c55e' : validationStatus === 'adjusting' ? '#facc15' : '#ef4444';

  if (isCompleted) {
    return (
        <div className="h-[100dvh] bg-brand-600 flex flex-col items-center justify-center text-white p-8 text-center animate-fadeIn">
            <div className="w-24 h-24 bg-white rounded-full flex items-center justify-center mb-8 shadow-2xl animate-bounce">
                <svg className="w-12 h-12 text-brand-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"></path></svg>
            </div>
            <h2 className="text-3xl font-black mb-4 uppercase">Gửi thành công!</h2>
            <p className="opacity-90 text-lg">Mã phiên: <span className="font-mono bg-black/20 px-2 rounded font-bold">{sessionId}</span></p>
            <p className="mt-6 opacity-80">Hãy kiểm tra màn hình máy tính của bạn.</p>
        </div>
    );
  }

  return (
    <div className="h-[100dvh] bg-black flex flex-col relative overflow-hidden touch-none py-safe">
        {/* Loading Overlay */}
        {isUploading && (
            <div className="absolute inset-0 z-[60] bg-black/80 backdrop-blur-sm flex flex-col items-center justify-center text-white">
                <div className="w-16 h-16 border-4 border-brand-500 border-t-transparent rounded-full animate-spin mb-4"></div>
                <div className="font-bold text-xl uppercase tracking-widest">Đang tải ảnh lên...</div>
                <div className="text-xs text-gray-400 mt-2">Vui lòng không đóng trình duyệt</div>
            </div>
        )}

        <div className="absolute top-0 left-0 right-0 p-4 z-50 flex flex-col items-center pointer-events-none">
            {!capturedImage && (
                <div className={`px-6 py-4 rounded-3xl backdrop-blur-md border-2 transition-all duration-300 text-center shadow-lg flex flex-col ${validationStatus === 'valid' ? 'bg-green-600/90 border-green-400' : 'bg-black/60 border-white/20'}`}>
                    <span className="text-white font-black text-xs uppercase tracking-widest mb-1 block">{feedbackMessage}</span>
                    <span className="text-white text-lg font-bold leading-tight px-2">{instruction}</span>
                </div>
            )}
            <div className="mt-2 text-[8px] text-white/40 font-mono">Phiên: {sessionId}</div>
        </div>

        <div className="flex-1 relative flex items-center justify-center bg-gray-900 overflow-hidden">
            {cameraError ? (
                <div className="text-white text-center p-6 bg-black/80 rounded-2xl border border-red-500 m-4">
                    <p className="font-bold">{cameraError}</p>
                    <button onClick={() => window.location.reload()} className="mt-4 px-6 py-2 bg-white text-black rounded-full font-bold">Thử lại</button>
                </div>
            ) : capturedImage ? (
                <div className="relative h-full w-full flex items-center justify-center p-4 bg-black">
                    <img src={capturedImage} className="max-h-full max-w-full rounded shadow-2xl object-contain" alt="Preview" />
                </div>
            ) : (
                <>
                    <video ref={videoRef} autoPlay playsInline className={`absolute inset-0 w-full h-full object-cover ${facingMode === 'user' ? 'transform -scale-x-100' : ''}`} />
                    <svg viewBox="0 0 100 100" className="absolute inset-0 w-full h-full opacity-90 pointer-events-none z-20">
                        <defs><mask id="m"><rect x="0" y="0" width="100" height="100" fill="white" /><ellipse cx="50" cy={topMarginPercent + 35} rx={32} ry={38} fill="black" /></mask></defs>
                        <rect x="0" y="0" width="100" height="100" fill="rgba(0,0,0,0.6)" mask="url(#m)" />
                        <ellipse cx="50" cy={topMarginPercent + 35} rx={32} ry={38} fill="none" stroke={overlayColor} strokeWidth="0.5" strokeDasharray="2,2" />
                    </svg>
                </>
            )}

            {countdown !== null && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/40 z-[100] backdrop-blur-sm">
                    <span className="text-9xl font-black text-white animate-ping">{countdown}</span>
                </div>
            )}
        </div>

        <div className="bg-black/95 p-6 pb-12 z-50 flex flex-col items-center gap-4 border-t border-gray-800">
            <input type="file" ref={fileInputRef} onChange={handleFileUpload} accept="image/*" className="hidden" />

            {capturedImage ? (
                <div className="flex w-full gap-4 max-w-sm">
                    <button onClick={() => setCapturedImage(null)} disabled={isUploading} className="flex-1 py-4 bg-gray-800 text-white rounded-2xl font-bold uppercase text-xs border border-gray-700 active:bg-gray-700">Chụp lại</button>
                    <button onClick={handleUpload} disabled={isUploading} className="flex-[2] py-4 bg-brand-600 text-white rounded-2xl font-bold shadow-xl flex items-center justify-center gap-2 uppercase text-xs active:bg-brand-700">
                        {isUploading ? "Đang gửi..." : "Sử dụng ảnh này"}
                    </button>
                </div>
            ) : (
                <div className="flex items-center justify-between w-full max-w-sm px-4 gap-4">
                    {/* Upload Button */}
                    <div className="flex flex-col items-center gap-1">
                        <button onClick={() => fileInputRef.current?.click()} className="w-14 h-14 rounded-full bg-gray-800 flex items-center justify-center text-gray-400 border border-gray-600 active:bg-gray-700 transition-all" title="Upload">
                            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12"></path></svg>
                        </button>
                        <span className="text-[9px] font-black uppercase text-gray-500">Tải ảnh</span>
                    </div>

                    {/* Flip Camera */}
                    <div className="flex flex-col items-center gap-1">
                        <button onClick={() => setFacingMode(f => f === 'user' ? 'environment' : 'user')} className="w-14 h-14 rounded-full bg-white/20 flex items-center justify-center text-white backdrop-blur border border-white/10 active:bg-white/30 transition-all">
                            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path></svg>
                        </button>
                        <span className="text-[9px] font-black uppercase text-gray-500">Đổi Cam</span>
                    </div>

                    {/* Shutter Button (Center) */}
                    <button onClick={() => setCountdown(3)} disabled={countdown !== null} className={`w-24 h-24 rounded-full border-4 flex items-center justify-center transition-all ${validationStatus === 'valid' ? 'border-green-500 bg-white shadow-[0_0_30px_rgba(34,197,94,0.5)]' : 'border-gray-500 bg-gray-700'}`}>
                        <div className={`w-20 h-20 rounded-full transition-colors ${validationStatus === 'valid' ? 'bg-green-600' : 'bg-gray-500'}`}></div>
                    </button>

                    {/* Auto Button */}
                    <div className="flex flex-col items-center gap-1">
                        <button onClick={() => setIsAutoCaptureEnabled(!isAutoCaptureEnabled)} className={`w-14 h-14 rounded-xl flex flex-col items-center justify-center border-2 transition-all active:scale-95 ${isAutoCaptureEnabled ? 'bg-brand-600 border-brand-400 text-white shadow-lg shadow-brand-500/50' : 'bg-gray-800 border-gray-600 text-gray-500'}`}>
                            <svg className={`w-6 h-6 mb-0.5 ${isAutoCaptureEnabled ? 'animate-pulse' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z"></path></svg>
                        </button>
                        <span className={`text-[9px] font-black uppercase ${isAutoCaptureEnabled ? 'text-brand-500' : 'text-gray-500'}`}>Auto</span>
                    </div>
                </div>
            )}
        </div>
        <canvas ref={canvasRef} className="hidden" />
        <canvas ref={analysisCanvasRef} className="hidden" />
    </div>
  );
};

export default MobileCaptureClient;

payload.text:
Lỗi **"Not found"** trong log của bạn thường do Google Apps Script không tìm thấy File dựa trên ID đã lưu trong `ScriptProperties` (có thể do file đã bị xóa, nằm trong thùng rác, hoặc phân quyền thư mục bị thay đổi). 

Ngoài ra, code Apps Script cũ của bạn đang dùng `e.postData.contents` nhưng thi thoảng Google lại đẩy dữ liệu vào `e.parameter` tùy thuộc vào cách trình duyệt gửi (CORS preflight).

Dưới đây là bản cập nhật **Google Apps Script (V8)** và **Database Service** để xử lý triệt để lỗi này, đảm bảo việc đồng bộ diễn ra mượt mà:

### 1. Cập nhật Google Apps Script (Copy & Ghi đè toàn bộ)
*Lưu ý: Sau khi dán, hãy nhấn "Triển khai" -> "Quản lý các bản triển khai" -> Chỉnh sửa -> Chọn "Phiên bản mới" -> Hoàn tất.*

```javascript
/**
 * ID PHOTO BOOTH API V3 - ULTRA STABLE
 */

function doGet(e) { return handleRequest(e); }
function doPost(e) { return handleRequest(e); }

function handleRequest(e) {
  var lock = LockService.getScriptLock();
  lock.tryLock(15000); // Đợi tối đa 15s

  try {
    var result = { success: false };
    var data = {};

    // 1. Phân tích dữ liệu đầu vào linh hoạt
    if (e.postData && e.postData.contents) {
      try {
        data = JSON.parse(e.postData.contents);
      } catch (err) {
        data = e.parameter;
      }
    } else {
      data = e.parameter;
    }

    var action = data.action;
    var props = PropertiesService.getScriptProperties();

    // --- LOGIC XỬ LÝ ---

    if (action === 'savePhoto') {
      var folder = getFolder();
      // Lưu dưới dạng JSON file
      var photoObj = {
        id: data.id,
        dataUrl: data.dataUrl,
        settings: data.settings,
        timestamp: new Date().getTime()
      };

      var fileName = "PHOTO_" + data.id + ".json";
      // Xóa file cũ nếu tồn tại để tránh rác
      var oldId = props.getProperty("MAP_" + data.id);
      if (oldId) {
        try { DriveApp.getFileById(oldId).setTrashed(true); } catch(i){}
      }

      var file = folder.createFile(fileName, JSON.stringify(photoObj), MimeType.PLAIN_TEXT);
      props.setProperty("MAP_" + data.id, file.getId());

      result.success = true;
      result.id = data.id;
    } 

    else if (action === 'getPhoto') {
      var fileId = props.getProperty("MAP_" + data.id);
      if (fileId) {
        try {
          var file = DriveApp.getFileById(fileId);
          if (file.isTrashed()) {
             props.deleteProperty("MAP_" + data.id);
             result.error = "File in trash";
          } else {
             var content = file.getBlob().getDataAsString();
             result.photo = JSON.parse(content);
             result.success = true;
          }
        } catch (err) {
          // Nếu File ID không tồn tại thực tế, xóa map để polling biết là chưa có
          props.deleteProperty("MAP_" + data.id);
          result.error = "File not found on Drive";
        }
      } else {
        result.success = false;
        result.message = "Waiting for upload...";
      }
    }

    else if (action === 'saveConfig') {
      if (data.config) {
         props.setProperty('app_config', JSON.stringify(data.config));
         result.success = true;
      }
    }

    else if (action === 'getConfig') {
      var config = props.getProperty('app_config');
      result.success = true;
      result.config = config ? JSON.parse(config) : null;
    }

  } catch (error) {
    result = { success: false, error: error.toString() };
  } finally {
    lock.releaseLock();
  }

  return ContentService.createTextOutput(JSON.stringify(result))
    .setMimeType(ContentService.MimeType.JSON);
}

function getFolder() {
  var props = PropertiesService.getScriptProperties();
  var folderId = props.getProperty("MAIN_FOLDER_ID");
  var folder;
  if (folderId) {
    try { folder = DriveApp.getFolderById(folderId); } catch (e) { folder = null; }
  }
  if (!folder) {
    var folders = DriveApp.getFoldersByName("ID_Photo_Booth_Data");
    folder = folders.hasNext() ? folders.next() : DriveApp.createFolder("ID_Photo_Booth_Data");
    props.setProperty("MAIN_FOLDER_ID", folder.getId());
  }
  return folder;
}
```

### 2. Cập nhật mã nguồn Frontend
Cập nhật `databaseService.ts` để bỏ qua các lỗi "Not found" giả (khi ảnh đang được xử lý trên Drive) và tiếp tục polling thay vì dừng lại.

