    return () => { isMountedRef.current = false; };
  }, [selectedSize, config.googleScriptUrl]);

  const pollForPhoto = async () => {
      if (!isMountedRef.current || status !== 'waiting') return;

      try {
          setPollCount(prev => prev + 1);
          // Gọi lấy ảnh, skipRetry=true để không bị block UI
          const photo = await getPhotoById(sessionIdRef.current, config.googleScriptUrl, true);

          if (photo && photo.dataUrl) {
              if (!isMountedRef.current) return;
              setStatus('found');

              setTimeout(() => {
                  if (isMountedRef.current) {
                      setStatus('downloading');
                      onPhotoReceived(photo.dataUrl);
                  }
              }, 800);
              return;
          }
      } catch (e) {
          // Lỗi im lặng để tiếp tục polling
      }

      if (isMountedRef.current && status === 'waiting') {
          timeoutRef.current = setTimeout(pollForPhoto, 2000);
      }
  };

  useEffect(() => {
      pollForPhoto();
      return () => { if (timeoutRef.current) clearTimeout(timeoutRef.current); };
