                </div>
                <h2 className="text-2xl font-black text-gray-800 dark:text-white uppercase tracking-tight">Đã nhận ảnh!</h2>
                <p className="text-gray-500 mt-2 text-sm">Đang chuyển vào trình chỉnh sửa...</p>
            </div>
        ) : (
            <>
                <div className="mb-6">
                    <h2 className="text-xl font-black text-gray-800 dark:text-white uppercase tracking-tight mb-1">Thiết bị liên kết</h2>
                    <div className="flex items-center justify-center gap-2">
