                    </div>
                </div>

                <div className="relative mx-auto w-52 h-52 mb-8 p-2 bg-white rounded-2xl shadow-inner border border-gray-100 flex items-center justify-center">
                    {qrUrl ? (
                        <img src={qrUrl} alt="QR Code" className="w-full h-full object-contain" />
                    ) : (
                        <div className="animate-spin w-8 h-8 border-4 border-brand-200 border-t-brand-600 rounded-full"></div>
                    )}
                </div>

                <div className="space-y-4">
                    <div className="bg-slate-50 dark:bg-gray-900/50 p-4 rounded-xl text-left border border-slate-100 dark:border-gray-700">
                         <div className="flex gap-3 mb-2">
                            <div className="w-5 h-5 rounded-full bg-brand-100 text-brand-600 flex items-center justify-center font-bold text-[10px] shrink-0">1</div>
