Lỗi **"Not found"** mà bạn thấy trong Console máy tính xuất hiện vì một trong hai lý do:
1.  **Độ trễ của Google Drive:** Sau khi điện thoại upload xong, Google Drive cần 1-2 giây để đồng bộ ID file trên toàn hệ thống. Nếu máy tính hỏi ngay lập tức, script sẽ báo lỗi không tìm thấy file.
2.  **CORS & Method:** Trình duyệt đôi khi gửi yêu cầu `OPTIONS` (Preflight) trước khi gửi `POST`, khiến script không nhận diện được `action`.

Dưới đây là bộ code **sửa lỗi triệt để** cho cả 3 phần: **Google Apps Script**, **Database Service** và **Mobile Capture**.

### 1. Cập nhật Google Apps Script (Bản V9 - Ổn định nhất)
Bạn hãy copy đè toàn bộ nội dung này vào file `.gs` trên Google Apps Script, sau đó **Triển khai phiên bản mới** (Deploy -> New Deployment).

```javascript
/**
 * GOOGLE APPS SCRIPT V9 - ULTRA STABLE FOR REACT BOOTH
 * Hỗ trợ Polling tốc độ cao và tự động sửa lỗi ID
 */

function doGet(e) { return handleRequest(e); }
function doPost(e) { return handleRequest(e); }

function handleRequest(e) {
  var lock = LockService.getScriptLock();
  lock.tryLock(15000); // Đợi 15s để tránh tranh chấp dữ liệu

  try {
    var result = { success: false };
    var data = {};

    // 1. Phân tích dữ liệu (Flexible Parser)
    if (e && e.postData && e.postData.contents) {
      try {
        data = JSON.parse(e.postData.contents);
      } catch (err) {
        data = e.parameter;
      }
    } else if (e && e.parameter) {
      data = e.parameter;
    }

    var action = data.action || "";
    var props = PropertiesService.getScriptProperties();

    // --- A. LƯU ẢNH (Điện thoại gọi) ---
    if (action === 'savePhoto') {
      var folder = getFolder();
      var sid = data.id;

      // Xóa dấu vết cũ nếu có
      var oldFileId = props.getProperty("MAP_" + sid);
      if (oldFileId) { try { DriveApp.getFileById(oldFileId).setTrashed(true); } catch(i){} }

      var photoObj = {
        id: sid,
        dataUrl: data.dataUrl,
        settings: data.settings,
        timestamp: new Date().getTime()
      };

      var file = folder.createFile("SID_" + sid + ".json", JSON.stringify(photoObj), MimeType.PLAIN_TEXT);
      props.setProperty("MAP_" + sid, file.getId());

      result.success = true;
      result.id = sid;
    } 

    // --- B. LẤY ẢNH (Máy tính Polling) ---
    else if (action === 'getPhoto') {
      var sid = data.id;
      var fileId = props.getProperty("MAP_" + sid);

      if (fileId) {
        try {
          var file = DriveApp.getFileById(fileId);
          var content = file.getBlob().getDataAsString();
          result.photo = JSON.parse(content);
          result.success = true;
        } catch (err) {
          // File tồn tại trong map nhưng không tìm thấy trên Drive (có thể bị xóa)
          // Trả về false nhưng không báo error để máy tính tiếp tục đợi
          result.success = false;
          result.message = "Syncing..."; 
        }
      } else {
        result.success = false;
        result.message = "Waiting for mobile...";
      }
    }

    // --- C. CẤU HÌNH ---
    else if (action === 'saveConfig') {
      if (data.config) {
        props.setProperty('app_config', JSON.stringify(data.config));
        result.success = true;
      }
    } else if (action === 'getConfig') {
      var cfg = props.getProperty('app_config');
      result.success = true;
      result.config = cfg ? JSON.parse(cfg) : null;
    }

    else {
      result.error = "Unknown action: " + action;
    }

  } catch (error) {
    result = { success: false, error: error.toString() };
  } finally {
    lock.releaseLock();
  }

  return ContentService.createTextOutput(JSON.stringify(result))
    .setMimeType(ContentService.MimeType.JSON);
}

function getFolder() {
  var props = PropertiesService.getScriptProperties();
  var folderId = props.getProperty("MAIN_FOLDER_ID");
  var folder;
  if (folderId) {
    try { folder = DriveApp.getFolderById(folderId); } catch (e) { folder = null; }
  }
  if (!folder) {
    var folders = DriveApp.getFoldersByName("ID_Photo_Booth_Data");
    folder = folders.hasNext() ? folders.next() : DriveApp.createFolder("ID_Photo_Booth_Data");
    props.setProperty("MAIN_FOLDER_ID", folder.getId());
  }
  return folder;
}
```

### 2. Cập nhật Frontend (React)

Tôi sẽ cập nhật lại `databaseService.ts` để xử lý lỗi "Not found" một cách thông minh và `MobileCameraLink.tsx` để polling chính xác hơn.

