const callAppsScript = async (action: string, payload: any = {}, overrideUrl?: string): Promise<any> => {
    const url = getScriptUrl(overrideUrl);
    if (!url) return { success: false, error: "Missing URL" };

    try {
        const body = JSON.stringify({ 
            action, 
            ...payload, 
            _t: Date.now() 
        });

        // Sử dụng POST cho tất cả các action để tránh giới hạn URL length và cache
        const response = await fetch(url, {
            method: 'POST',
            body: body,
            headers: { 'Content-Type': 'text/plain;charset=utf-8' }
        });

        if (!response.ok) throw new Error(`HTTP ${response.status}`);

        const data = await response.json();
        return data;
    } catch (error) {
        console.warn(`Apps Script [${action}] error:`, error);
        return { success: false, error: String(error) };
    }
